{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C61"],
      "claim": "Samidorphan, a morphinan opioid structurally close to the query, had an absolute oral bioavailability of 69% in healthy male volunteers after a 2 mg oral dose versus IV, supporting high F for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Pethidine, an N-methyl opioid analgesic, had an absolute oral bioavailability of 0.52 (0.47–0.61) after oral administration in healthy subjects, supporting high oral F for a related opioid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Morphine, the closest morphinan comparator, has an oral bioavailability of 30–40% in healthy volunteers with immediate-release dosing, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Pentazocine, a benzomorphan opioid, had an oral bioavailability of 0.18 in normal subjects, below the 20% threshold; this is the main contradictory analogue but is outweighed by more relevant morphinan and opioid data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "High: the closest morphinan analogues (samidorphan 69%, morphine ~30–40%) and the opioid pethidine (~52%) all exceed 20% oral bioavailability; the low pentazocine value (~18%) is outweighed by these more relevant high-F data.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (hydrocodone) is present in the evidence set.",
    "The contradictory pentazocine data indicate that some morphinan opioids can have F<20%, so the exact magnitude of first-pass metabolism for hydrocodone is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

